'use client';

import React from 'react';
import Link from 'next/link';
import Image from 'next/image';

import { svg } from '../svg';
import { stores } from '../stores';
import { Routes } from '../routes';

import { components } from '../components';
import type { ProductType } from '../types';

type Props = {
  product: ProductType;
};

export const ShopItem: React.FC<Props> = ({ product }) => {
  const { addToCart } = stores.useCartStore();

  const { list: cart } = stores.useCartStore();
  const { list: wishlist } = stores.useWishlistStore();

  const { removeFromWishlist, addToWishlist } = stores.useWishlistStore();

  const ifInCart = cart.find((item) => item.id === product.id);
  const ifInWishlist = wishlist.find((item) => item.id === product.id);
  const quantity = cart.find((item) => item.id === product.id)?.quantity;

  const PlusSvg: React.FC = () => {
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width={30}
        height={30}
        fill="none"
      >
        <circle cx={15} cy={15} r={15} fill="#1E2538" />
        <path
          fill="#fff"
          d="M15.726 15.707V19h-1.423v-3.293H11v-1.414h3.303V11h1.423v3.293H19v1.414h-3.274Z"
        />
      </svg>
    );
  };

  return (
    <div>
      <div style={{ position: 'relative' }}>
        <Link href={`${Routes.PRODUCT}/${product.id}`}>
          <Image
            src={product.image}
            alt={product.name}
            width={0}
            height={0}
            sizes="100vw"
            priority={true}
            style={{
              width: '100%',
              height: '100%',
              borderRadius: 20,
              marginBottom: 12,
            }}
          />
        </Link>
        {product.oldPrice && <components.Sale style={{ top: 10, right: 10 }} />}
        <div
          style={{
            position: 'absolute',
            top: 10,
            left: 10,
            paddingLeft: 5,
            paddingRight: 5,
            borderRadius: 30,
            display: 'flex',
            gap: 4,
            alignItems: 'center',
            flexDirection: 'row',
            paddingTop: 2,
            paddingBottom: 2,
            backgroundColor: 'var(--white-color)',
          }}
        >
          <svg.StarSvg />
          <span
            style={{
              fontSize: 12,
              lineHeight: 1.2,
              color: 'var(--text-color)',
              marginTop: 2,
              fontFamily: 'var(--font-league-spartan)',
            }}
          >
            {product.rating.toFixed(1)}
          </span>
        </div>
        <button
          style={{
            position: 'absolute',
            bottom: 50,
            right: 10,
            borderRadius: '50%',
          }}
          onClick={(e) => {
            e.stopPropagation();
            e.preventDefault();
            if (ifInWishlist) {
              removeFromWishlist(product);
            } else {
              addToWishlist(product);
            }
          }}
        >
          <svg.HeartSvg />
        </button>
        {!ifInCart && (
          <button
            style={{
              position: 'absolute',
              bottom: 10,
              right: 10,
              borderRadius: '50%',
            }}
            onClick={(e) => {
              e.stopPropagation();
              e.preventDefault();
              addToCart(product);
            }}
          >
            <PlusSvg />
          </button>
        )}
        {ifInCart && (
          <div
            style={{
              position: 'absolute',
              bottom: 10,
              right: 10,
              borderRadius: '50%',
              width: 30,
              height: 30,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              backgroundColor: 'var(--accent-color)',
            }}
          >
            <span
              className="t16"
              style={{ marginTop: 2, color: 'var(--main-color)' }}
            >
              {quantity}
            </span>
          </div>
        )}
      </div>

      <h6 style={{ textAlign: 'center', marginBottom: 2 }}>{product.name}</h6>
      <div
        style={{
          textAlign: 'center',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 4,
        }}
      >
        {product.oldPrice && (
          <span
            style={{
              fontSize: 12,
              color: 'var(--text-color)',
              textDecoration: 'line-through',
              fontFamily: 'var(--font-league-spartan)',
            }}
          >
            ${product.oldPrice}
          </span>
        )}
        <span style={{ textAlign: 'center', display: 'block' }} className="t16">
          ${product.price}
        </span>
      </div>
    </div>
  );
};
