'use client';

import React, { useEffect, useState } from 'react';
import { DotLottieReact } from '@lottiefiles/dotlottie-react';

import { components } from '../../../components';

import type { Game } from '../../../types';
import { Box, Container, Paper, Grid } from '@mui/material';
import { useDeviceDetect } from '@/hooks/useDeviceDetect';
import { stores } from '@/stores';
import { items } from '@/items';
import { useGameListPreload } from '@/hooks/useGamePreloader';

type Props = {
  similarGames: Game[];
  game: Game | null;
};

export const GamePlayContent: React.FC<Props> = ({ game, similarGames }) => {
  const { isDesktop } = useDeviceDetect();
  const [loaded, setLoaded] = useState<boolean>(false);
  const { user, initAuth, isLoggedIn, isLoadedCurrentUser, token } =
    stores.useUserStore();

  useGameListPreload(similarGames);

  useEffect(() => {
    if (!user) {
      initAuth();
    }

    return () => {
      // console.log('Out page');
    };
  }, [user]);

  const renderHeader = () => {
    return (
      <components.Header
        title={game?.title}
        showGoBack={true}
        showBasket={true}
      />
    );
  };
  const renderBackground = () => {
    return <components.Background />;
  };

  const renderGameDesktop = () => {
    return (
      <Container maxWidth="xl">
        <Grid container spacing={2}>
          <Grid
            size={{
              xs: 12,
              sm: game!.isPortrait ? 4 : 8,
              md: game!.isPortrait ? 4 : 8,
              lg: game!.isPortrait ? 3 : 9,
            }}
            sx={{
              height: game!.isPortrait ? '94vh' : '81vh',
              overflow: 'hidden',
              position: 'relative',
            }}
          >
            {!loaded && (
              <Box
                sx={{
                  position: 'absolute',
                  top: 0,
                  bottom: 0,
                  left: 0,
                  right: 0,
                  margin: 0,
                  padding: 0,
                  backgroundColor: 'var(--white-color)',
                  display: 'flex',
                  alignContent: 'center',
                  justifyContent: 'center',
                  flexDirection: 'column',
                }}
              >
                <Paper
                  elevation={3}
                  sx={{
                    height: '100%',
                    width: '100%',
                    margin: '0 auto',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    flexDirection: 'column',
                  }}
                >
                  <Box component="div" sx={{ height: '40vh' }}>
                    <DotLottieReact
                      src="https://lottie.host/85e09882-d694-49bd-8923-555538ca0e84/86HtlRXSdD.lottie"
                      loop
                      autoplay
                      backgroundColor="transparent"
                    />
                  </Box>
                  <span className="t18 text-center mx-2">
                    Chargement du jeu en cours veuillez patienter s'il vous
                    plait
                  </span>
                </Paper>
              </Box>
            )}

            <iframe
              src={`${game?.url}?q=${token}&gameId=${game?.id}`}
              title={game?.title || ''}
              allowFullScreen
              sandbox="allow-scripts allow-same-origin allow-pointer-lock"
              style={{
                width: '100%',
                height: '100%',
                border: 'none',
                overflow: 'hidden',
                display: 'block',
              }}
              onLoad={() => setTimeout(() => setLoaded(true), 2000)}
            />
          </Grid>

          <Grid
            size={{
              xs: 12,
              sm: game!.isPortrait ? 8 : 4,
              md: game!.isPortrait ? 8 : 4,
              lg: game!.isPortrait ? 9 : 3,
            }}
            sx={{
              height: '88vh',
              overflowY: 'auto',
              overflowX: 'hidden',
              position: 'relative',
            }}
          >
            <h3>Jeux qui pourraient vous intéresser</h3>
            <ul
              style={{
                marginTop: 20,
                display: 'grid',
                gap: 15,
                gridTemplateColumns: `repeat(${game!.isPortrait ? '5' : '2'}, 1fr)`,
              }}
            >
              {similarGames.map((gameItem) => {
                return (
                  <items.GameItem
                    key={gameItem.id}
                    game={gameItem}
                    height={'20vh'}
                  />
                );
              })}
            </ul>
          </Grid>
        </Grid>
      </Container>
    );
  };

  const renderGameMobile = () => {
    // Styles pour mode portrait
    const portraitStyles = {
      position: 'fixed',
      top: 42,
      bottom: 0,
      left: 0,
      right: 0,
      margin: 0,
      padding: 0,
      zIndex: 9,
      backgroundColor: 'transparent',
    };

    // Styles pour mode paysage
    const landscapeStyles = {
      position: 'fixed',
      top: '50%',
      left: '50%',
      width: 'calc(100dvh - 42px)',
      height: 'calc(100vw + 2px)',
      margin: 0,
      padding: 0,
      zIndex: 9,
      backgroundColor: 'transparent',
      transform: 'translate(-50%, -45%) rotate(90deg)',
      transformOrigin: 'center center',
    };

    return (
      <Box
        component="div"
        sx={game && game.isPortrait ? portraitStyles : landscapeStyles}
      >
        {!loaded && (
          <Box
            sx={{
              position: 'absolute',
              top: game && game.isPortrait ? 42 : 0,
              bottom: 0,
              left: 0,
              right: 0,
              width: '100%',
              margin: 0,
              padding: 0,
              backgroundColor: 'var(--white-color)',
              display: 'flex',
              alignContent: 'center',
              justifyContent: 'center',
              flexDirection: 'column',
            }}
          >
            <Paper
              elevation={3}
              sx={{
                height: '50vh',
                width: '90vw',
                margin: '0 auto',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                flexDirection: 'column',
              }}
            >
              <Box component="div" sx={{ height: '40vh' }}>
                <DotLottieReact
                  src="https://lottie.host/85e09882-d694-49bd-8923-555538ca0e84/86HtlRXSdD.lottie"
                  loop
                  autoplay
                  backgroundColor="transparent"
                />
              </Box>
              <span className="t18 text-center mx-2">
                Chargement du jeu en cours veuillez patienter s'il vous plait
              </span>
            </Paper>
          </Box>
        )}
        <iframe
          src={`${game?.url}?q=${token}&gameId=${game?.id}`}
          title="The Flow Color"
          allowFullScreen
          sandbox="allow-scripts allow-same-origin allow-pointer-lock"
          style={{
            width: '100%',
            height: '100%',
            border: 'none',
            display: 'block',
          }}
          onLoad={() => setTimeout(() => setLoaded(true), 2000)}
        />
      </Box>
    );
  };

  const renderContent = () => {
    if (isLoadedCurrentUser && isLoggedIn && game) {
      return isDesktop ? renderGameDesktop() : renderGameMobile();
    }
    return <></>;
  };

  const renderModal = () => {
    return <components.Modal />;
  };

  return (
    <components.Screen>
      {renderBackground()}
      {renderHeader()}
      {renderContent()}
      {renderModal()}
    </components.Screen>
  );
};
