'use client';

import React, { useCallback, useEffect, useState } from 'react';
import Box from '@mui/material/Box';
import { data } from '@/data';

import { stores } from '../stores';
import { Swiper, SwiperSlide } from 'swiper/react';
import { InputField } from './InputField';
import {
  Alert,
  Badge,
  CircularProgress,
  Link,
  Paper,
  Snackbar,
  SnackbarCloseReason,
  Stack,
  Typography,
} from '@mui/material';
import { Button } from '@/components/Button';
import { useDeviceDetect } from '@/hooks/useDeviceDetect';
import {
  servicesMobileMoney,
  servicesAirTimeMoney,
} from '@/constants/serviceMobileMoney';
import { primaryColor } from '@/styles/colors';
import { OTPInput } from './OtpInput';
import { validPhoneNumber } from '@/utils/phoneNumber_helper';
import { createAnonymousUser } from '@/data/authentication';
import { StatusEnum } from '@/enum/stateTransactionEnum';
import { useRouter } from 'next/navigation';
import { Routes } from '@/routes';
import { LocalStorageService } from '@/storages/local_storage_service';
import { DotLottieReact } from '@lottiefiles/dotlottie-react';
import { getUniqueGames } from '@/utils/game_helper';
import { CategoryBlocGameType } from '@/types/CategoryBlocGameType';
import {
  saveAllGamesIndexDb,
  saveCategoriesBlocGameIndexDb,
} from '@/storages/indexed_db_service';
import { TypeTransactionEnum } from '@/enum/typeTransactionEnum';
import { getServiceFromSubdomain } from '@/utils/subdomain_helper';

export const ModalSubscribe: React.FC = () => {
  const { isOpen, closeModal } = stores.useModalSubscribe();
  const { isDesktop } = useDeviceDetect();
  const [currentPricing, setCurrentPricing] = useState<string>('');
  const [numberCtrl, setNumberCtrl] = useState<string>('');
  const [numberNotConform, setNumberNotConform] = useState<string>('');
  const [otp, setOtp] = useState<string>('');
  const [paymentUrl, setPaymentUrl] = useState<string>('');
  const [paymentInWaitConfirmation, setPaymentInWaitConfirmation] =
    useState<boolean>(false);
  const [isCreditCard, displayCreditCardInput] = useState<boolean>(false);
  const { pricings, init } = stores.usePricingStore();
  const { user, initAuth: initUser, isLoggedIn } = stores.useUserStore();
  const [service, setService] = useState<string | null>(null);
  const [inSend, toogleInSend] = useState<boolean>(false);
  const [messageError, setMessageError] = useState<string>('');
  const [open, setOpen] = useState<boolean>(false);
  const [otpSent, setOtpSent] = useState<boolean>(false);
  const { setUser } = stores.useUserStore();
  const router = useRouter();

  const isAirTimeApp = pricings.some(
    (pricing) => pricing.type === TypeTransactionEnum.AIR_TIME,
  );

  useEffect(() => {
    if (isOpen) {
      init();
      initUser();
      setOtpSent(false);
      setOtp('');
      const metaThemeColor = document.querySelector('meta[name="theme-color"]');
      if (metaThemeColor) {
        metaThemeColor.setAttribute('content', '#F5FAFB');
      }
    }
  }, [isOpen, init, initUser]);

  useEffect(() => {
    if (isAirTimeApp && !service) {
      const subdomainService = getServiceFromSubdomain();
      if (subdomainService) {
        setService(subdomainService);
      }
    }
  }, [isAirTimeApp, service]);

  const handleClose = (
    event: React.SyntheticEvent | Event,
    reason?: SnackbarCloseReason,
  ) => {
    event.preventDefault();
    if (reason === 'clickaway') {
      return;
    }

    setOpen(false);
  };

  useEffect(() => {
    if (isLoggedIn) {
      setNumberCtrl(user?.phone_number || '');
      // User is logged in, you can perform actions here
    }
  }, [isLoggedIn]);

  const handleAuthentification = async () => {
    if (
      numberCtrl.trim().length >= 8 &&
      numberCtrl.trim().indexOf('+') === -1 &&
      validPhoneNumber(numberCtrl.trim())
    ) {
      toogleInSend(true);
      try {
        const response = await createAnonymousUser();
        if (!response.etat) {
          toogleInSend(false);
          throw new Error(
            response.message ||
              'Nous avons du mal à créer votre compte afin de valider votre achat',
          );
        }
        setUser(response.result.client);
      } catch (error) {
        toogleInSend(false);
        throw error;
      }
    } else {
      toogleInSend(false);
      throw new Error('Le numéro ne doit pas contenir de caractères spéciaux');
    }
  };

  const refreshGameApp = useCallback(async () => {
    const [gamesData] = await Promise.all([data.getGames()]);
    if (gamesData.length > 0) {
      const allGames = gamesData.flatMap(
        (gameWithCategorie) => gameWithCategorie.games,
      );
      const allGameFilter = getUniqueGames(allGames);

      // Mettre à jour dans l'indexDB
      await saveAllGamesIndexDb(allGameFilter);
      await saveCategoriesBlocGameIndexDb(gamesData as CategoryBlocGameType[]);
    }
  }, []);

  const handleSubscription = async () => {
    if (currentPricing === '') {
      throw new Error('Veuillez sélectionner un forfait');
    }
    if (numberCtrl.trim().length !== 10 || numberNotConform.trim().length > 0) {
      throw new Error('Veuillez entrer un numéro de téléphone valide');
    }
    if (service === null) {
      throw new Error('Veuillez sélectionner un mode de paiement');
    }
    if ((service === 'orangeci' || isAirTimeApp) && otp.trim().length !== 4) {
      throw new Error('Veuillez entrer le code OTP reçu');
    }
    toogleInSend(true);
    try {
      const response = await data.setSubscription({
        forfaitId: currentPricing,
        service: service!,
        numberTel: numberCtrl,
        otp: service === 'orangeci' || isAirTimeApp ? otp : undefined,
      });
      if (!response.etat) {
        toogleInSend(false);
        if (isAirTimeApp) {
          throw new Error(response.error![0]);
        }
        throw new Error('Paiement échoué: veuillez vérifier votre solde');
      }

      if (response.etat && response.result.subscriptionId) {
        // Subscription successful
        await refreshUser();
        await refreshGameApp();
        closeModal();
        const redirectUrl = LocalStorageService.getLocationRedirection();
        if (redirectUrl) {
          router.push(redirectUrl);
        }
      } else if (response.etat && response.result.transactionId) {
        setPaymentInWaitConfirmation(true);
        if (response.result.url) {
          setPaymentUrl(response.result.url);
          // Redirect to payment URL on new tab
          window.open(response.result.url, '_blank');
        }
        await fetchPaymentStatus(response.result.transactionId);
      }
    } catch (error) {
      toogleInSend(false);
      throw error;
    }
    // Proceed with subscription logic here
  };

  const refreshUser = useCallback(async () => {
    try {
      const freshUser = await data.getUser();
      if (freshUser) {
        setUser(freshUser);
      }
    } catch (error) {
      console.error(
        'Error refreshing user after subscription confirmation:',
        error,
      );
    }
  }, []);

  const fetchPaymentStatus = async (transactionId: string) => {
    try {
      // Polling the payment status every 3 seconds
      const intervalId = setInterval(async () => {
        const [order] = await Promise.all([data.getOrders(transactionId)]); // Assuming this endpoint gives payment status
        if (
          order.status === StatusEnum.DONE ||
          order.status === StatusEnum.REJECTED
        ) {
          clearInterval(intervalId);
          toogleInSend(false);
          if (order.status === StatusEnum.DONE) {
            await refreshUser();
            await refreshGameApp();
            closeModal();
            const redirectUrl = LocalStorageService.getLocationRedirection();
            if (redirectUrl) {
              router.push(redirectUrl);
            }
          } else {
            closeModal();
            router.push(`${Routes.SUBSCRIPTION_RESULT}/cancel/${order.ref}`);
          }
        }
      }, 3000);
    } catch (error) {
      toogleInSend(false);
      throw error;
    }
  };

  const handleSendOtp = async () => {
    if (numberCtrl.trim().length < 8 || numberNotConform.trim().length > 0) {
      throw new Error('Veuillez entrer un numéro de téléphone valide');
    }
    toogleInSend(true);
    try {
      if (!isLoggedIn) {
        await handleAuthentification();
      }
      const response = await data.sendSubscriptionOtp({
        numberTel: numberCtrl,
      });
      if (!response.etat) {
        throw new Error(
          response.message || "Nous n'avons pas pu envoyer le code OTP",
        );
      }
      setOtp('');
      setOtpSent(true);
      toogleInSend(false);
    } catch (error) {
      toogleInSend(false);
      throw error;
    }
  };

  const handleResendOtp = async (event: React.MouseEvent<HTMLSpanElement>) => {
    event.preventDefault();
    if (inSend) {
      return;
    }
    try {
      await handleSendOtp();
    } catch (error) {
      setMessageError(
        error instanceof Error ? error.message : 'Une erreur est survenue',
      );
      setOpen(true);
    }
  };

  const renderCategories = () => {
    return (
      <section style={{ marginBottom: 5 }}>
        <Swiper
          spaceBetween={14}
          slidesPerView={'auto'}
          onSlideChange={() => {}}
          onSwiper={(swiper) => {
            // console.log(swiper);
          }}
          style={{ padding: '0 20px' }}
        >
          {pricings
            .sort((a, b) => a.price - b.price)
            .map((pricing) => {
              return (
                <SwiperSlide key={pricing.id} style={{ width: 'auto' }}>
                  <button
                    style={{
                      border: `1px solid ${pricing.id === currentPricing ? 'var(--accent-color)' : '#C8CDD9'}`,
                      borderRadius: 50,
                      padding: '8px 18px',
                      marginTop: 5,
                      marginBottom: 10,
                      display: 'flex',
                      ...(pricing.id === currentPricing && {
                        backgroundColor: 'var(--accent-color)',
                        boxShadow: `-3px 2px 20px -2px var(--accent-color)`,
                      }),
                    }}
                    className="clickable"
                    onClick={(e) => {
                      e.preventDefault();
                      setCurrentPricing(pricing.id);
                    }}
                  >
                    <span
                      className="t16"
                      style={{ color: 'var(--main-color)' }}
                    >
                      {Number.parseInt(pricing.price.toString(), 10)} Frs/
                      {pricing.periode}
                    </span>
                  </button>
                </SwiperSlide>
              );
            })}
        </Swiper>
      </section>
    );
  };

  const renderProviderPayment = () => {
    return (
      <Box sx={{ paddingX: 5 }} component="div">
        <p style={{ textAlign: 'center', marginBottom: 20, marginTop: 10 }}>
          Choisissez votre mode de paiement
        </p>
        <Stack
          direction="row"
          alignItems="center"
          justifyContent="center"
          sx={{ width: '100%', gap: 1 }}
        >
          {servicesMobileMoney
            .filter((serviceMobile) => serviceMobile.type === 'mobile money')
            .map((serviceMobile) => (
              <Badge
                key={`service-${serviceMobile.name}`}
                color="secondary"
                overlap="circular"
                badgeContent=""
                variant="dot"
                invisible={!service || service !== serviceMobile.name}
              >
                <Paper
                  sx={{
                    borderRadius: 40,
                    width: { xs: 40, md: 60 },
                    height: { xs: 40, md: 60 },
                    cursor: 'pointer',
                    background: `center / cover no-repeat url("${serviceMobile.flag}")`,
                  }}
                  elevation={4}
                  onClick={(event) => {
                    event.stopPropagation(); // Empêche la propagation de l'événement de clic vers la carte
                    event.preventDefault();
                    setService(serviceMobile.name);
                    displayCreditCardInput(
                      serviceMobile.type === 'credit card',
                    );
                    if (numberCtrl.trim().length > 1) {
                      console.log('test');
                      if (
                        serviceMobile.startWith &&
                        !numberCtrl.trim().startsWith(serviceMobile.startWith)
                      ) {
                        setNumberNotConform(
                          `Le numéro doit commencer par ${serviceMobile.startWith}`,
                        );
                      } else {
                        setNumberNotConform('');
                      }
                    } else {
                      setNumberNotConform('');
                    }
                  }}
                />
              </Badge>
            ))}
        </Stack>
      </Box>
    );
  };

  const agreeCheckout = isAirTimeApp
    ? otpSent
      ? otp.trim().length === 4 && numberCtrl.trim().length === 10
      : numberCtrl.trim().length === 10 &&
        numberNotConform.trim().length === 0 &&
        !!service
    : (numberCtrl.length === 10 &&
        service !== null &&
        service !== 'orangeci' &&
        !isCreditCard) ||
      (service === 'orangeci' && otp.length === 4 && numberCtrl.length === 10);

  const renderAirtimeInput = () => {
    const serviceSelected = servicesAirTimeMoney.find(
      (serviceMobile) => serviceMobile.value === service,
    );

    if (!serviceSelected) {
      return (
        <Box sx={{ paddingX: 5 }} component="div">
          <Alert severity="warning">
            Service de paiement introuvable pour ce domaine.
          </Alert>
        </Box>
      );
    }

    return (
      <Box sx={{ paddingX: 5 }} component="div">
        <Stack
          direction="row"
          alignItems="center"
          justifyContent="center"
          spacing={1}
          sx={{ mb: 2 }}
        >
          <Paper
            sx={{
              borderRadius: 40,
              width: 32,
              height: 32,
              background: `center / cover no-repeat url("${serviceSelected.flag}")`,
            }}
            elevation={2}
          />
          <Typography variant="body2" className="body_font_primary">
            {serviceSelected.name}
          </Typography>
        </Stack>
        {!otpSent ? (
          <>
            <p style={{ textAlign: 'center', marginBottom: 20, marginTop: 10 }}>
              Entrez le numéro de téléphone à facturer
            </p>
            <InputField
              value={numberCtrl}
              onChange={(e) => {
                const value = e.target.value.trim();
                setNumberCtrl(value);
                if (value.length > 1) {
                  if (
                    serviceSelected.startWith &&
                    !value.startsWith(serviceSelected.startWith)
                  ) {
                    setNumberNotConform(
                      `Le numéro doit commencer par ${serviceSelected.startWith}`,
                    );
                  } else {
                    setNumberNotConform('');
                  }
                } else {
                  setNumberNotConform('');
                }
              }}
              autoFocus={true}
              inputType="tel"
              type="tel"
              placeholder="0XXXXXXXXX"
              containerStyle={{ marginBottom: 16 }}
            />
            {numberNotConform.trim().length > 0 && (
              <Alert sx={{ mb: 3 }} severity="error">
                {numberNotConform}
              </Alert>
            )}
          </>
        ) : (
          <>
            <p style={{ textAlign: 'center', marginBottom: 20, marginTop: 10 }}>
              Entrez le code OTP envoyé au {numberCtrl}
            </p>
            <Stack
              direction="row"
              alignItems="center"
              justifyContent="center"
              sx={{ width: '100%', mb: 2 }}
            >
              <OTPInput length={4} value={otp} onChange={setOtp} />
            </Stack>
            <Stack
              direction="row"
              alignItems="center"
              justifyContent="center"
              sx={{ width: '100%', mb: 1 }}
            >
              <span
                className="t16 main-color clickable"
                onClick={handleResendOtp}
                style={{ color: 'var(--main-color)', lineHeight: 1.2 }}
              >
                Renvoyer le code
              </span>
            </Stack>
          </>
        )}
      </Box>
    );
  };

  const renderNumberInput = () => {
    if (isCreditCard) {
      return <></>;
    }
    return (
      <Box sx={{ paddingX: 5 }} component="div">
        <p style={{ textAlign: 'center', marginBottom: 20, marginTop: 10 }}>
          Entrez le numéro de téléphone à facturer
        </p>
        <InputField
          value={numberCtrl}
          onChange={(e) => {
            setNumberCtrl(e.target.value.trim());
            if (e.target.value.trim().length > 1) {
              const serviceSelected = servicesMobileMoney.find(
                (serviceMobile) => serviceMobile.name === service,
              );
              if (serviceSelected) {
                if (
                  serviceSelected.startWith &&
                  !e.target.value.trim().startsWith(serviceSelected.startWith)
                ) {
                  setNumberNotConform(
                    `Le numéro doit commencer par ${serviceSelected.startWith}`,
                  );
                } else {
                  setNumberNotConform('');
                }
              }
            } else {
              setNumberNotConform('');
            }
          }}
          autoFocus={true}
          inputType="tel"
          type="tel"
          placeholder="0XXXXXXXXX"
          containerStyle={{ marginBottom: 16 }}
        />
        {numberNotConform.trim().length > 0 && (
          <Alert sx={{ mb: 3 }} severity="error">
            {numberNotConform}
          </Alert>
        )}
        {service === 'orangeci' && numberNotConform.trim().length === 0 && (
          <Box component="div" sx={{ padding: 0, marginTop: -2 }}>
            <Typography
              sx={{ mb: 1 }}
              variant="body2"
              color="text.primary"
              className="body_font_primary"
            >
              Pour finaliser le paiement vous devez obtenir un code à 4 chiffres
              en composant le{' '}
              <Link
                sx={{ color: primaryColor }}
                className="title-service"
                underline="hover"
                href={'tel:#144*82#'}
                rel="noreferrer"
                target="_blank"
              >
                #144*82#
              </Link>{' '}
              puis faite entrer le code généré ici 👇👇👇
            </Typography>
            <Stack
              direction="row"
              alignItems="center"
              justifyContent="center"
              sx={{ width: '100%', mb: 2 }}
            >
              <OTPInput length={4} value={otp} onChange={setOtp} />
            </Stack>
          </Box>
        )}
      </Box>
    );
  };

  const renderButtonCheckout = () => {
    return (
      <Box sx={{ paddingX: 5, marginTop: 3 }} component="div">
        <Stack
          direction="row"
          alignItems="center"
          justifyContent="center"
          sx={{ width: '100%', mb: 2, mt: 3 }}
        >
          {inSend ? (
            <Box
              component="div"
              sx={{
                display: 'flex',
                flexDirection: 'row',
                alignItems: 'center',
                justifyContent: 'center',
                height: 50,
                width: '100%',
              }}
            >
              <CircularProgress size={30} color="inherit" />
            </Box>
          ) : (
            <Button
              label={
                isAirTimeApp && !otpSent
                  ? 'Envoyer le code'
                  : 'Payer maintenant'
              }
              aria-label="Checkout now"
              containerStyle={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                flexDirection: 'row',
                width: '50%',
              }}
              style={{ padding: 0, margin: 0 }}
              onClick={async (e) => {
                e.stopPropagation();
                e.preventDefault();
                try {
                  if (isAirTimeApp && !otpSent) {
                    await handleSendOtp();
                    return;
                  }
                  if (!isLoggedIn) {
                    await handleAuthentification();
                  }
                  await handleSubscription();
                } catch (error) {
                  setMessageError(
                    error instanceof Error
                      ? error.message
                      : 'Une erreur est survenue',
                  );
                  setOpen(true);
                }
              }}
            />
          )}
        </Stack>
      </Box>
    );
  };

  if (!isOpen) return null;

  return (
    <div
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        backgroundColor: 'rgba(30, 37, 56, 0.6)',
        zIndex: 101,
      }}
      onClick={() => {
        closeModal();
      }}
    >
      <div
        style={{
          position: 'absolute',
          left: isDesktop ? '20%' : 0,

          right: isDesktop ? '20%' : 0,
          bottom: 0,
          height: '75%',
          backgroundColor: '#F5FAFB',
          borderTopRightRadius: 30,
          borderTopLeftRadius: 30,
          zIndex: 99999,
        }}
        onClick={(e) => {
          e.stopPropagation();
        }}
      >
        {paymentInWaitConfirmation ? (
          <Box
            component="div"
            sx={{ padding: 5, height: '100%', width: '100%' }}
          >
            <Stack
              direction="column"
              alignItems="center"
              justifyContent="center"
              sx={{ height: '100%', width: '100%' }}
            >
              <Box component="div" sx={{ height: '30%' }}>
                <DotLottieReact
                  src="https://lottie.host/10fa923e-610c-432a-ad01-b946fc114198/MeKv4X6uHC.lottie"
                  loop
                  autoplay
                  backgroundColor="transparent"
                />
              </Box>
              {paymentUrl.length === 0 ? (
                <span className="t18 text-center mx-2">
                  Nous attendons la confirmation de votre paiement.
                </span>
              ) : (
                <>
                  <span className="t18 text-center mx-2">
                    Nous avons lancer votre paiement wave. Si la fenêtre de
                    paiement a été bloquée, veuillez cliquer sur le bouton
                    ci-dessous.
                  </span>
                  <Button
                    label="Ouvrir Wave"
                    onClick={() => {
                      window.open(paymentUrl, '_blank');
                    }}
                  />
                </>
              )}
            </Stack>
          </Box>
        ) : (
          <>
            <h2
              style={{
                textTransform: 'capitalize',
                textAlign: 'center',
                marginBottom: 20,
                marginTop: 10,
              }}
            >
              Choisissez un forfait
            </h2>
            {renderCategories()}
            {currentPricing !== '' && !isAirTimeApp && renderProviderPayment()}
            {currentPricing !== '' &&
              !isAirTimeApp &&
              service &&
              renderNumberInput()}
            {currentPricing !== '' && isAirTimeApp && renderAirtimeInput()}
            {agreeCheckout && renderButtonCheckout()}
          </>
        )}
        <Snackbar
          anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
          open={open}
          autoHideDuration={5000}
          onClose={handleClose}
        >
          <Alert
            onClose={handleClose}
            severity="warning"
            variant="filled"
            sx={{ width: '100%' }}
          >
            {messageError}
          </Alert>
        </Snackbar>
      </div>
    </div>
  );
};
