'use client';

import React, { useRef } from 'react';
import Link from 'next/link';
import Image from 'next/image';

import { svg } from '../svg';
import { stores } from '../stores';
import { Routes } from '../routes';

import type { Game } from '../types';
import { Button } from '@/components/Button';
import { URLS_ASSETS } from '@/config';
import { useRouter } from 'next/navigation';
import { LocalStorageService } from '@/storages/local_storage_service';
import { GamePreloadService } from '@/services/GamePreloadService';
import { useGamePreload } from '@/hooks/useGamePreloader';
import { UserType } from '@/types/UserType';
import { hasActiveSubscription } from '@/utils/subscription_helper';

type Props = {
  game: Game;
  height?: number | string;
  enablePreload?: boolean;
};

export const GameItem: React.FC<Props> = ({
  game,
  height = '25vh',
  enablePreload = true,
}) => {
  const router = useRouter();
  const { openModal: openModalSubscribe } = stores.useModalSubscribe();
  const containerRef = useRef<HTMLDivElement>(null);
  const { user } = stores.useUserStore();
  // Hook de préchargement
  const { handleMouseEnter, handleMouseLeave, status } = useGamePreload(
    game,
    containerRef,
    {
      enabled: enablePreload,
      enableHover: true,
      enableVisibility: true,
      hoverDelay: 200,
      visibilityThreshold: 0.3,
      visibilityRootMargin: '100px',
    },
  );

  const ifInWishlist = false;

  const handlePlayClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();

    const url = `${Routes.GAME_PLAY}/${game?.title.replaceAll(' ', '_')}/${game?.id}`;

    if (user && hasActiveSubscription(user.subscriptions)) {
      // console.log(`🎯 Clic sur "${game.title}" - Statut: ${status}`);

      if (status === 'loaded') {
        // console.log(`⚡ Chargement instantané du jeu préchargé!`);
      } else if (status === 'loading') {
        // console.log(`⏳ Jeu en cours de préchargement...`);
      } else {
        // console.log(`🔄 Chargement normal du jeu`);
      }

      router.push(url);
      return;
    }

    LocalStorageService.saveLocationRedirection(url);
    openModalSubscribe();
  };

  return (
    <div
      className="game-item"
      ref={containerRef}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <div style={{ position: 'relative' }}>
        <Link
          href={`${Routes.GAME}/${game.title.replaceAll(' ', '_')}/${game.id}`}
        >
          <Image
            src={`${URLS_ASSETS.GAMES}/${game.profilPicture}`}
            alt={game.title}
            width={0}
            height={0}
            sizes="100vw"
            priority={true}
            style={{
              width: '100%',
              height,
              borderRadius: 20,
              marginBottom: 12,
            }}
          />
        </Link>

        {game.ratings.length > 0 && (
          <div
            style={{
              position: 'absolute',
              top: 10,
              left: 10,
              paddingLeft: 5,
              paddingRight: 5,
              borderRadius: 30,
              display: 'flex',
              gap: 4,
              alignItems: 'center',
              flexDirection: 'row',
              paddingTop: 2,
              paddingBottom: 2,
              backgroundColor: 'var(--white-color)',
            }}
          >
            <svg.StarSvg />
            <span
              style={{
                fontSize: 12,
                lineHeight: 1.2,
                color: 'var(--text-color)',
                marginTop: 2,
                fontFamily: 'var(--font-league-spartan)',
              }}
            >
              {game.ratings.reduce((acc, item) => acc + item.value, 0) /
                game.ratings.length}
            </span>
          </div>
        )}

        <div
          style={{
            position: 'absolute',
            bottom: 5,
            right: 5,
            paddingLeft: 5,
            paddingRight: 5,
            borderRadius: 30,
            paddingBottom: 2,
            width: '50%',
            display: 'flex',
            alignItems: 'flex-end',
            justifyContent: 'flex-end',
            flexDirection: 'column',
            gap: 10,
          }}
        >
          <Button
            label="Jouer"
            containerStyle={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'flex-end',
              flexDirection: 'row',
              width: '100%',
            }}
            style={{ padding: 0, margin: 0, height: 30 }}
            onClick={handlePlayClick}
          />
        </div>
      </div>

      <h5 style={{ textAlign: 'center', marginBottom: 2 }}>{game.title}</h5>
      <div
        style={{
          textAlign: 'center',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 4,
        }}
      ></div>
    </div>
  );
};
