'use client';
import { data } from '@/data';
import { getGameByIdIndexDb } from '@/storages/indexed_db_service';
import { Game } from '@/types/GameType';
import { useEffect, useState, useCallback } from 'react';
import { GamePlayContent } from './GamePlayContent';

type Props = {
  id: string;
};

export const GamePlayPageClient: React.FC<Props> = ({ id }) => {
  const [game, setGame] = useState<Game | null>(null);
  const [similarGames, setSimilarGames] = useState<Game[]>([]);

  // 1. Charger ensuite depuis API pour mise à jour
  const fetchAndUpdateGames = useCallback(async () => {
    try {
      const [{ game: gameInfo, similarGame: similarGamesInfo }] =
        await Promise.all([data.getGamesByID(id)]);
      if (gameInfo && similarGamesInfo) {
        setGame(gameInfo);
        setSimilarGames(similarGamesInfo);
      }
    } catch (error) {
      console.error('Erreur lors du chargement des données depuis API:', error);
    }
  }, [id]);

  // 2. Charger d'abord depuis indexDB
  const loadGamesFromIndexDB = useCallback(async () => {
    try {
      const gamesFromDB = await getGameByIdIndexDb(id);
      if (gamesFromDB && gamesFromDB.url && gamesFromDB.url.length > 3) {
        setGame(gamesFromDB);
      }
      await fetchAndUpdateGames();
    } catch (error) {
      console.error(
        'Erreur lors du chargement des jeux depuis IndexDB:',
        error,
      );
    }
  }, [id]);

  useEffect(() => {
    loadGamesFromIndexDB();
  }, []);
  return <GamePlayContent game={game} similarGames={similarGames} />;
};
